import{_ as e,o,c as s,ag as d}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Hidrolimpiadoras","description":"","frontmatter":{},"headers":[],"relativePath":"es/car-wash/pressure-washers.md","filePath":"es/car-wash/pressure-washers.md"}'),r={name:"es/car-wash/pressure-washers.md"};function n(i,a,l,c,t,u){return o(),s("div",null,[...a[0]||(a[0]=[d('<h1 id="hidrolimpiadoras" tabindex="-1">Hidrolimpiadoras <a class="header-anchor" href="#hidrolimpiadoras" aria-label="Permalink to &quot;Hidrolimpiadoras&quot;">​</a></h1><p>Las hidrolimpiadoras son la opción de autoservicio: el jugador aparca, se acerca a una hidrolimpiadora y limpia el vehículo nivel a nivel. Se paga cada nivel de suciedad eliminado.</p><h2 id="donde-estan" tabindex="-1">Dónde están <a class="header-anchor" href="#donde-estan" aria-label="Permalink to &quot;Dónde están&quot;">​</a></h2><p>Dos maneras, y puedes usar las dos:</p><ul><li><strong>Props del mundo</strong>: cada prop indicado en <code>ManualModels</code> se convierte en una hidrolimpiadora, allí donde el mapa tenga uno. Por defecto es <code>prop_gas_airunit01</code>, el poste de aire de las gasolineras.</li><li><strong>Estaciones que colocas tú</strong>: añade una entrada a <code>ManualStations</code> en <code>/nay</code>, colócate donde la quieras y pulsa <strong>Usar mi posición</strong>.</li></ul><p>Con <code>ShowBlips</code> activado, las estaciones colocadas aparecen en el mapa.</p><h2 id="como-las-usan-los-jugadores" tabindex="-1">Cómo las usan los jugadores <a class="header-anchor" href="#como-las-usan-los-jugadores" aria-label="Permalink to &quot;Cómo las usan los jugadores&quot;">​</a></h2><ul><li>Con <code>InteractionMode</code> en <code>key</code>, los jugadores se acercan a la hidrolimpiadora y pulsan <strong>E</strong>.</li><li>Con <code>target</code>, usan el ojo del target (ox_target o qb-target).</li></ul><p>Se muestran el nivel de suciedad del vehículo y el precio por nivel. La limpieza quita un nivel cada <code>ManualSecondsPerLevel</code> segundos, y cada nivel cuesta <code>ManualPricePerLevel</code>, cobrado de la cuenta definida en <code>Account</code>. Los jugadores pueden parar en cualquier momento y solo pagan lo que han limpiado.</p><p>Desactiva todas las hidrolimpiadoras con <code>ManualEnabled</code>. Todos los ajustes están en la página <a href="/es/car-wash/settings#hidrolimpiadoras">Ajustes</a>.</p>',10)])])}const h=e(r,[["render",n]]);export{m as __pageData,h as default};
